        UPDATE MEMBERS 
        SET STATUS = 3, 
        	LEAVE_DATE = #{leaveDate}
	    WHERE MEMBERS_ID = #{membersId}

        UPDATE MEMBERS 
        SET STATUS = 1, 
        	CARD_NUM = #{cardNum}
	    WHERE MEMBERS_ID = #{membersId}

        UPDATE MEMBERS 
        SET STATUS = 2
	    WHERE MEMBERS_ID = #{value}

        UPDATE MEMBERS 
        SET LOAN_COUNT = LOAN_COUNT + 1
	    WHERE MEMBERS_ID = #{value}

        UPDATE MEMBERS 
        SET LOAN_COUNT = LOAN_COUNT - 1
	    WHERE MEMBERS_ID = #{value}
